 @Test void getInvitation_InviterInviteeAndUnauthorizedPartitions(){User inviter=user(U),invitee=user(8L),other=user(9L);when(users.findById(U)).thenReturn(Optional.of(inviter));when(users.findById(8L)).thenReturn(Optional.of(invitee));when(users.findById(9L)).thenReturn(Optional.of(other));CoParentInvitation item=new CoParentInvitation();item.setId(9L);item.setPet(pet(U));item.setInviter(inviter);item.setInviteeUser(invitee);item.setInviteeEmail("x@y.com");item.setRole(PetCoParent.CoParentRole.editor);item.setStatus(CoParentInvitation.InvitationStatus.pending);when(invitations.findById(9L)).thenReturn(Optional.of(item));assertThat(service.getInvitation(U,9L).getInviterId()).isEqualTo(U);assertThat(service.getInvitation(8L,9L).getInviteeUserId()).isEqualTo(8L);assertThatThrownBy(()->service.getInvitation(9L,9L)).isInstanceOf(ForbiddenException.class);}
