 @Test void removeCoParent_SuccessNotifiesAndMissingTargetIsRejected(){when(users.findById(U)).thenReturn(Optional.of(user(U)));when(pets.findById(P)).thenReturn(Optional.of(pet(U)));PetCoParent cp=new PetCoParent();cp.setUser(user(8L));when(coParents.findByIdAndPetId(3L,P)).thenReturn(Optional.of(cp));service.removeCoParent(U,P,3L);verify(coParents).delete(cp);verify(notifications).createNotification(org.mockito.ArgumentMatchers.eq(8L),org.mockito.ArgumentMatchers.eq(U),org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.eq("co_parent_removed"),org.mockito.ArgumentMatchers.eq(P));when(coParents.findByIdAndPetId(3L,P)).thenReturn(Optional.empty());assertThatThrownBy(()->service.removeCoParent(U,P,3L)).isInstanceOf(com.petcare.backend.exception.ResourceNotFoundException.class);}
 @Test void getPet_ResponseMapsAllergyAndChronicConditions(){Pet p=pet(U);when(pets.findByIdAndAccessibleByUserId(P,U)).thenReturn(Optional.of(p));HealthCondition allergy=new HealthCondition();allergy.setType(HealthCondition.ConditionType.allergy);allergy.setTitle("dust");HealthCondition chronic=new HealthCondition();chronic.setType(HealthCondition.ConditionType.chronic_disease);chronic.setTitle("skin");when(conditions.findByPetIdAndIsActiveTrue(P)).thenReturn(List.of(allergy,chronic));assertThat(service.getPetById(principal,P).getAllergies()).contains("dust");assertThat(service.getPetById(principal,P).getMedicalConditions()).contains("skin");}
