@Test void petAndInvitationLists_MapPopulatedAndEmptyPages(){when(users.findById(U)).thenReturn(Optional.of(user(U)));Pet owned=pet(U);when(pets.findAllAccessibleByUserId(U)).thenReturn(List.of(owned));assertThat(service.getMyPets(principal)).hasSize(1);when(pets.findByIdAndAccessibleByUserId(P,U)).thenReturn(Optional.of(owned));PetCoParent cp=new PetCoParent();cp.setPet(owned);cp.setUser(user(8L));cp.setInvitedBy(user(U));cp.setRole(PetCoParent.CoParentRole.viewer);when(coParents.findByPetId(P)).thenReturn(List.of(cp));assertThat(service.getCoParents(principal,P)).hasSize(1);CoParentInvitation invitation=new CoParentInvitation();invitation.setId(9L);invitation.setPet(owned);invitation.setInviter(user(U));invitation.setInviteeUser(user(8L));invitation.setStatus(CoParentInvitation.InvitationStatus.pending);when(invitations.findByInviteeUserIdAndStatusAndExpiresAtAfterOrderByCreatedAtDesc(eq(U),any(),any(),any())).thenReturn(new org.springframework.data.domain.PageImpl<>(List.of(invitation)));when(invitations.findByInviterIdOrderByCreatedAtDesc(eq(U),any())).thenReturn(new org.springframework.data.domain.PageImpl<>(List.of()));assertThat(service.getIncomingInvitations(U,0,1).getContent()).hasSize(1);assertThat(service.getOutgoingInvitations(U,0,99).getContent()).isEmpty();}
 @Test void invitationAcceptAndDecline_SuccessfullySaveCoParentAndNotify(){User owner=user(8L),invitee=user(U);when(users.findById(U)).thenReturn(Optional.of(invitee));Pet target=pet(8L);CoParentInvitation accepted=new CoParentInvitation();accepted.setId(9L);accepted.setPet(target);accepted.setInviter(owner);accepted.setInviteeUser(invitee);accepted.setRole(PetCoParent.CoParentRole.editor);accepted.setStatus(CoParentInvitation.InvitationStatus.pending);accepted.setExpiresAt(java.time.LocalDateTime.now().plusHours(1));when(invitations.findById(9L)).thenReturn(Optional.of(accepted));when(invitations.save(any())).thenAnswer(i->i.getArgument(0));service.acceptCoParentInvitation(U,9L);assertThat(accepted.getStatus()).isEqualTo(CoParentInvitation.InvitationStatus.accepted);verify(coParents).save(any());verify(notifications).createNotification(eq(8L),eq(U),anyString(),anyString(),eq("co_parent_accepted"),eq(P));CoParentInvitation declined=new CoParentInvitation();declined.setId(10L);declined.setPet(target);declined.setInviter(owner);declined.setInviteeUser(invitee);declined.setStatus(CoParentInvitation.InvitationStatus.pending);declined.setExpiresAt(java.time.LocalDateTime.now().plusHours(1));when(invitations.findById(10L)).thenReturn(Optional.of(declined));service.declineCoParentInvitation(U,10L);assertThat(declined.getStatus()).isEqualTo(CoParentInvitation.InvitationStatus.declined);verify(notifications).createNotification(eq(8L),eq(U),anyString(),anyString(),eq("co_parent_declined"),eq(P));}
 @Test void avatarUpdateTransactionSynchronization_DeletesOldOnCommitAndNewOnRollback(){Pet target=pet(U);target.setAvatarUrl("old-url");when(pets.findByIdAndAccessibleByUserId(P,U)).thenReturn(Optional.of(target));org.springframework.web.multipart.MultipartFile avatar=org.mockito.Mockito.mock(org.springframework.web.multipart.MultipartFile.class);when(avatar.isEmpty()).thenReturn(false);when(files.storePetAvatar(avatar,U)).thenReturn(com.petcare.backend.dto.upload.UploadFileResponse.builder().mediaUrl("new-url").build());org.mockito.ArgumentCaptor<org.springframework.transaction.support.TransactionSynchronization> callback=org.mockito.ArgumentCaptor.forClass(org.springframework.transaction.support.TransactionSynchronization.class);try(org.mockito.MockedStatic<org.springframework.transaction.support.TransactionSynchronizationManager> transaction=org.mockito.Mockito.mockStatic(org.springframework.transaction.support.TransactionSynchronizationManager.class)){service.updatePet(U,P,new UpdatePetRequest(),avatar);transaction.verify(()->org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(callback.capture()));callback.getValue().afterCompletion(org.springframework.transaction.support.TransactionSynchronization.STATUS_COMMITTED);callback.getValue().afterCompletion(org.springframework.transaction.support.TransactionSynchronization.STATUS_ROLLED_BACK);}verify(files).deleteByUrl("old-url");verify(files).deleteByUrl("new-url");}
 @Test void avatarCreateRollbackAndSaveFailure_CleansNewFile(){when(users.findById(U)).thenReturn(Optional.of(user(U)));Species selected=new Species();selected.setId(S);when(species.findById(S)).thenReturn(Optional.of(selected));org.springframework.web.multipart.MultipartFile avatar=org.mockito.Mockito.mock(org.springframework.web.multipart.MultipartFile.class);when(avatar.isEmpty()).thenReturn(false);when(files.storePetAvatar(avatar,U)).thenReturn(com.petcare.backend.dto.upload.UploadFileResponse.builder().mediaUrl("created-url").build());org.mockito.ArgumentCaptor<org.springframework.transaction.support.TransactionSynchronization> callback=org.mockito.ArgumentCaptor.forClass(org.springframework.transaction.support.TransactionSynchronization.class);try(org.mockito.MockedStatic<org.springframework.transaction.support.TransactionSynchronizationManager> transaction=org.mockito.Mockito.mockStatic(org.springframework.transaction.support.TransactionSynchronizationManager.class)){service.createPet(U,request(),avatar);transaction.verify(()->org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(callback.capture()));callback.getValue().afterCompletion(org.springframework.transaction.support.TransactionSynchronization.STATUS_COMMITTED);callback.getValue().afterCompletion(org.springframework.transaction.support.TransactionSynchronization.STATUS_ROLLED_BACK);org.mockito.Mockito.doThrow(new RuntimeException("cleanup failed")).when(files).deleteByUrl("created-url");callback.getValue().afterCompletion(org.springframework.transaction.support.TransactionSynchronization.STATUS_ROLLED_BACK);}verify(files,times(2)).deleteByUrl("created-url");org.mockito.Mockito.doThrow(new RuntimeException("db failed")).when(pets).save(any());assertThatThrownBy(()->service.createPet(U,request(),avatar)).isInstanceOf(RuntimeException.class);verify(files,times(3)).deleteByUrl("created-url");}
 @Test void inviteCodeCollision_ThrowsAfterAllAttempts(){when(users.findById(U)).thenReturn(Optional.of(user(U)));when(pets.findById(P)).thenReturn(Optional.of(pet(U)));when(users.findByEmail("x@y.com")).thenReturn(Optional.of(user(8L)));when(invitations.existsByInviteCode(anyString())).thenReturn(true);com.petcare.backend.dto.pet.request.CreateCoParentInvitationRequest request=new com.petcare.backend.dto.pet.request.CreateCoParentInvitationRequest();request.setInviteeEmail("x@y.com");request.setRole("viewer");assertThatThrownBy(()->service.createCoParentInvitation(U,P,request)).isInstanceOf(com.petcare.backend.exception.ConflictException.class);verify(invitations,times(5)).existsByInviteCode(anyString());}
 @Test void missingEntities_ThrowFromAllOptionalLookups(){when(users.findById(U)).thenReturn(Optional.of(user(U)));when(pets.findByIdAndAccessibleByUserId(P,U)).thenReturn(Optional.empty());assertThatThrownBy(()->service.updatePet(U,P,new UpdatePetRequest(),null)).isInstanceOf(BadRequestException.class);when(pets.findById(P)).thenReturn(Optional.empty());assertThatThrownBy(()->service.deletePet(principal,P)).isInstanceOf(BadRequestException.class);when(pets.findByIdAndAccessibleByUserId(P,U)).thenReturn(Optional.empty());assertThatThrownBy(()->service.getCoParents(principal,P)).isInstanceOf(BadRequestException.class);when(pets.findById(P)).thenReturn(Optional.of(pet(U)));com.petcare.backend.dto.pet.request.UpdateCoParentRoleRequest role=new com.petcare.backend.dto.pet.request.UpdateCoParentRoleRequest();role.setRole("viewer");when(coParents.findByIdAndPetId(7L,P)).thenReturn(Optional.empty());assertThatThrownBy(()->service.updateCoParentRole(U,P,7L,role)).isInstanceOf(com.petcare.backend.exception.ResourceNotFoundException.class);when(pets.findById(P)).thenReturn(Optional.empty());com.petcare.backend.dto.pet.request.CreateCoParentInvitationRequest invitation=new com.petcare.backend.dto.pet.request.CreateCoParentInvitationRequest();invitation.setInviteeEmail("missing@y.com");invitation.setRole("viewer");assertThatThrownBy(()->service.createCoParentInvitation(U,P,invitation)).isInstanceOf(com.petcare.backend.exception.ResourceNotFoundException.class);when(pets.findById(P)).thenReturn(Optional.of(pet(U)));when(users.findByEmail("missing@y.com")).thenReturn(Optional.empty());assertThatThrownBy(()->service.createCoParentInvitation(U,P,invitation)).isInstanceOf(com.petcare.backend.exception.ResourceNotFoundException.class);when(species.findById(S)).thenReturn(Optional.empty());assertThatThrownBy(()->service.createPet(principal,request())).isInstanceOf(BadRequestException.class);}
 @Test void updatePet_ReplacesHealthConditionsAndIgnoresBlankTitles(){Pet target=pet(U);when(pets.findByIdAndAccessibleByUserId(P,U)).thenReturn(Optional.of(target));HealthCondition old=new HealthCondition();old.setIsActive(true);when(conditions.findByPetIdAndTypeAndIsActiveTrue(P,HealthCondition.ConditionType.allergy)).thenReturn(List.of(old));when(conditions.findByPetIdAndTypeAndIsActiveTrue(P,HealthCondition.ConditionType.chronic_disease)).thenReturn(List.of());UpdatePetRequest update=new UpdatePetRequest();update.setAllergies(List.of(" dust ","dust"," "));update.setMedicalConditions(List.of("skin"));service.updatePet(U,P,update,null);assertThat(old.getIsActive()).isFalse();verify(conditions).saveAll(List.of(old));verify(conditions,times(2)).save(any(HealthCondition.class));}
